public partial class MainWindow : Window {
 Raster? image,flow;byte[] mask=[];readonly Stack<byte[]> history=new();readonly List<(double x,double y)> polygon=new();bool drawing,busy;Point last,pan;double time;readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(16)};readonly System.Diagnostics.Stopwatch watch=System.Diagnostics.Stopwatch.StartNew();double previous;
 static readonly JsonSerializerOptions Json=new(){IncludeFields=true,WriteIndented=true};
 public MainWindow(){InitializeComponent();Discover();StartGuidedInterface();timer.Tick+=(_,_)=>{double now=watch.Elapsed.TotalSeconds;if(Playing.IsChecked==true)time+=now-previous;previous=now;if(!busy)Render();};timer.Start();Closed+=(_,_)=>timer.Stop();}
 void Discover(){var paths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);try{var f=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"VRChatCreatorCompanion/settings.json");if(File.Exists(f)){using var j=JsonDocument.Parse(File.ReadAllText(f));if(j.RootElement.TryGetProperty("userProjects",out var a))foreach(var p in a.EnumerateArray())if(p.GetString() is string s&&Directory.Exists(Path.Combine(s,"Assets")))paths.Add(s);}}catch(Exception ex){Status.Text="VCC discovery: "+ex.Message;}
 try{string f=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"UnityHub/projects-v1.json");if(File.Exists(f)){using var j=JsonDocument.Parse(File.ReadAllText(f));if(j.RootElement.TryGetProperty("data",out var data))foreach(var p in data.EnumerateObject())if(Directory.Exists(Path.Combine(p.Name,"Assets")))paths.Add(p.Name);}}catch{}foreach(var p in paths)Projects.Items.Add(p);if(Projects.Items.Count>0)Projects.SelectedIndex=0;var active=paths.Where(p=>File.Exists(Path.Combine(p,"Temp/UnityLockfile"))).ToArray();if(active.Length>0){Projects.SelectedItem=active[0];Status.Text="Open Unity projects detected: "+string.Join(", ",active.Select(Path.GetFileName));}string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Unity/Hub/Editor");Editors.Text="Installed Unity: "+(Directory.Exists(root)?string.Join(", ",Directory.GetDirectories(root).Select(Path.GetFileName)):"browse a custom installation");}
 static double Number(TextBox box,double min,double max){if(!double.TryParse(box.Text,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out double v)||!double.IsFinite(v)||v<min||v>max)throw new Exception($"Invalid value '{box.Text}'. Expected {min} to {max}.");return v;}
 FlowSettings Settings()=>new(){speed=(float)Number(Speed,.01,100),angle=(float)Angle.Value,tilingX=(float)Number(TileX,.01,1000),tilingY=(float)Number(TileY,.01,1000),rotation=(float)Number(Rotation,0,360),emission=(float)Number(Emission,0,100),hdr=(float)Number(Hdr,-10,16),tint=Tint.Text,shader=((ComboBoxItem)Shader.SelectedItem).Content.ToString()!};
 async Task Work(Func<Task> action){if(busy)return;busy=true;ApplyButton.IsEnabled=false;Targets.IsEnabled=false;Projects.IsEnabled=false;RestoreButton.IsEnabled=false;try{await action();}catch(Exception ex){Status.Text=ex.Message;MessageBox.Show(this,ex.Message,"Texture Flow");}finally{busy=false;ApplyButton.IsEnabled=true;Targets.IsEnabled=true;Projects.IsEnabled=true;RefreshConnection();}}
 void Check(){if(image==null)throw new Exception("Open a base texture first.");}
 void Remember(){while(history.Count>=4){var a=history.Reverse().Skip(1).ToArray();history.Clear();foreach(var m in a)history.Push(m);}history.Push((byte[])mask.Clone());}
 void SetImage(Raster r){image=r;sourceTexturePath=null;BaseLabel.Text=$"Original texture: {r.W} x {r.H}";CanvasHost.Height=CanvasHost.Width*r.H/r.W;mask=new byte[r.W*r.H];history.Clear();polygon.Clear();Outline.Points.Clear();Status.Text=$"{r.W} × {r.H} • Select the stripe or region to animate.";}
 async void OpenBase(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter=ProjectTextures.FileFilter};if(d.ShowDialog()==true)await Work(async()=>{await LoadTextureAsync(d.FileName,false);});}
 async void OpenFlow(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter=ProjectTextures.FileFilter};if(d.ShowDialog()==true)await Work(async()=>{await LoadTextureAsync(d.FileName,true);});}
 void Demo(object s,RoutedEventArgs e){if(busy)return;byte[] p=new byte[512*512*4],f=new byte[128*128*4];for(int y=0;y<512;y++)for(int x=0;x<512;x++){int i=(y*512+x)*4;byte v=(byte)(Math.Abs(x-256+45*Math.Sin(y/70.0))<45?12:175);p[i]=v;p[i+1]=v;p[i+2]=v;p[i+3]=255;}for(int y=0;y<128;y++)for(int x=0;x<128;x++){int i=(y*128+x)*4;byte v=(byte)(110+140*Math.Pow(Math.Sin(y*.13+Math.Sin(x*.08)),8));f[i]=v;f[i+1]=v;f[i+2]=(byte)(v/2);f[i+3]=255;}SetImage(new(512,512,p));flow=new(128,128,f);mask=Selection.Select(image!,256,256,32,true,false,0,0,0);FlowLabel.Text="Demo energy pattern";Steps.SelectedIndex=1;Status.Text="Demo ready: the energy moves inside the selected stripe. Change direction, speed or glow, then open step 3.";}
 void Undo(object s,RoutedEventArgs e){if(!busy&&history.TryPop(out var m))mask=m;}
 void Clear(object s,RoutedEventArgs e){if(busy||image==null)return;Remember();Array.Clear(mask);polygon.Clear();Outline.Points.Clear();}
 async Task Cleanup(string mode)=>await Work(async()=>{Check();Remember();int r=(int)Number(Radius,1,128);mask=await Task.Run(()=>mode=="holes"?Selection.Holes(mask,image!.W,image.H):mode=="smooth"?Selection.Filter(Selection.Filter(mask,image!.W,image.H,r,"min"),image.W,image.H,r,"max"):Selection.Filter(mask,image!.W,image.H,r,mode));});
 async void Grow(object s,RoutedEventArgs e)=>await Cleanup("max");async void Shrink(object s,RoutedEventArgs e)=>await Cleanup("min");async void Feather(object s,RoutedEventArgs e)=>await Cleanup("blur");async void Smooth(object s,RoutedEventArgs e)=>await Cleanup("smooth");async void FillHoles(object s,RoutedEventArgs e)=>await Cleanup("holes");
 (double x,double y) Tex(Point p)=>(Math.Clamp(p.X/Preview.ActualWidth*image!.W,0,image.W-1),Math.Clamp(p.Y/Preview.ActualHeight*image.H,0,image.H-1));
 void Merge(byte[] m,bool add){if(add)for(int i=0;i<m.Length;i++)mask[i]=Math.Max(mask[i],m[i]);else mask=m;}
 async void PointerDown(object s,MouseButtonEventArgs e){if(busy||image==null)return;if(e.ChangedButton==MouseButton.Middle){pan=e.GetPosition(Viewport);Preview.CaptureMouse();return;}if(e.ChangedButton!=MouseButton.Left)return;var p=e.GetPosition(Preview);var t=Tex(p);int tool=Tool.SelectedIndex;
 if(tool<3){double tol=Tolerance.Value,ht,st,vt;try{ht=Number(Hue,0,180);st=Number(Sat,0,1);vt=Number(Val,0,1);}catch(Exception ex){Status.Text=ex.Message;return;}bool add=Add.IsChecked==true;await Work(async()=>{Remember();var m=await Task.Run(()=>Selection.Select(image,(int)t.x,(int)t.y,tol,tool==0,tool==2,ht,st,vt));Merge(m,add);});}
 else if(tool<5){Remember();drawing=true;last=p;Preview.CaptureMouse();Paint(t.x,t.y);}
 else {if(polygon.Count==0){Remember();Outline.Points.Clear();}polygon.Add(t);Outline.Points.Add(p);if(tool==6&&e.ClickCount==2){FinishPolygon();return;}if(tool==5){drawing=true;Preview.CaptureMouse();}}
 }
 void Paint(double x,double y)=>Selection.Brush(mask,image!.W,image.H,x,y,BrushSize.Value,Softness.Value,Tool.SelectedIndex==4);
 void PointerMove(object s,MouseEventArgs e){if(busy||image==null)return;if(e.MiddleButton==MouseButtonState.Pressed&&Preview.IsMouseCaptured){var p=e.GetPosition(Viewport);Viewport.ScrollToHorizontalOffset(Viewport.HorizontalOffset+pan.X-p.X);Viewport.ScrollToVerticalOffset(Viewport.VerticalOffset+pan.Y-p.Y);pan=p;return;}if(!drawing||e.LeftButton!=MouseButtonState.Pressed)return;var point=e.GetPosition(Preview);var t=Tex(point);if(Tool.SelectedIndex<5){var a=Tex(last);double d=Math.Sqrt(Math.Pow(t.x-a.x,2)+Math.Pow(t.y-a.y,2));int steps=Math.Max(1,(int)(d/Math.Max(1,BrushSize.Value/5)));for(int i=1;i<=steps;i++)Paint(a.x+(t.x-a.x)*i/steps,a.y+(t.y-a.y)*i/steps);last=point;}else{polygon.Add(t);Outline.Points.Add(point);}}
 void PointerUp(object s,MouseButtonEventArgs e){Preview.ReleaseMouseCapture();if(drawing&&Tool.SelectedIndex==5)FinishPolygon();drawing=false;}
 void FinishPolygon(){if(polygon.Count>=3)Merge(Selection.Polygon(image!.W,image.H,polygon),Add.IsChecked==true);polygon.Clear();Outline.Points.Clear();drawing=false;}
 void Zoom(object s,MouseWheelEventArgs e){double size=Math.Clamp(CanvasHost.Width*(e.Delta>0?1.15:1/1.15),128,8192);CanvasHost.Width=size;CanvasHost.Height=image==null?size:size*image.H/image.W;e.Handled=true;}
 void Render(){if(image==null)return;FlowSettings settings;Color tint;try{settings=Settings();tint=(Color)ColorConverter.ConvertFromString(settings.tint);}catch{return;}int w=Math.Min(640,image.W),h=Math.Max(1,(int)((double)w*image.H/image.W));var p=new byte[w*h*4];bool before=Before.IsChecked==true,baseOn=ShowBase.IsChecked==true,flowOn=ShowFlow.IsChecked==true,overlay=ShowMask.IsChecked==true,glow=ShowGlow.IsChecked==true;double angle=settings.angle*Math.PI/180,rot=settings.rotation*Math.PI/180,cs=Math.Cos(rot),sn=Math.Sin(rot),dx=Math.Cos(angle)*settings.speed*time,dy=Math.Sin(angle)*settings.speed*time,gain=glow?1+settings.emission*Math.Pow(2,settings.hdr):1;var im=image;var fl=flow;var m=mask;
 Parallel.For(0,h,y=>{for(int x=0;x<w;x++){int sx=x*im.W/w,sy=y*im.H/h,i=(sy*im.W+sx),o=(y*w+x)*4;double a=before?0:m[i]/255.0;double u=(x+.5)/w-.5,v=1-(y+.5)/h-.5;double fx=(u*cs-v*sn)*settings.tilingX+.5-dx,fy=(u*sn+v*cs)*settings.tilingY+.5-dy;int fi=fl==null?0:((Math.Min(fl.H-1,(int)((1-(fy-Math.Floor(fy)))*fl.H)))*fl.W+(int)((fx-Math.Floor(fx))*fl.W))*4;for(int c=0;c<3;c++){double b=(baseOn||before)?im.Pixels[i*4+c]:32,energy=fl==null?0:fl.Pixels[fi+c]*(c==0?tint.B:c==1?tint.G:tint.R)/255.0*gain;double val=before?b:flowOn&&fl!=null?b*(1-a)+energy*a:b;if(!before&&overlay)val=val*(1-a*.25)+(c==2?255:c==1?80:180)*a*.25;p[o+c]=(byte)Math.Clamp(val,0,255);}p[o+3]=im.Pixels[i*4+3];}});
 Preview.Source=new Raster(w,h,p).Bitmap();}
 void DirectionPreset(object s,RoutedEventArgs e){Angle.Value=double.Parse(((Button)s).Tag.ToString()!,System.Globalization.CultureInfo.InvariantCulture);}
 void SpeedPreset(object s,RoutedEventArgs e){Speed.Text=((Button)s).Tag.ToString()!;}
 void BrowseProject(object s,RoutedEventArgs e){var d=new OpenFolderDialog{Title="Select Unity project root (contains Assets and ProjectSettings)"};if(d.ShowDialog()==true){if(!Directory.Exists(Path.Combine(d.FolderName,"ProjectSettings"))){Status.Text="Select the Unity project root.";return;}SelectProject(d.FolderName);}}
 async void Export(object s,RoutedEventArgs e)=>await Work(async()=>{Check();if(flow==null)throw new Exception("Open a moving texture first.");var settings=Settings();_=(Color)ColorConverter.ConvertFromString(settings.tint);string project=SelectedProject??throw new Exception("Choose your Unity project first.");string directory=await ExportAssetsAsync(project,settings);Status.Text="Files created in "+directory+". Unity will create the material when it imports. Use Create & Apply to assign it to an avatar part.";});

 void WriteAssets(string folder,FlowSettings settings){image!.Save(Path.Combine(folder,"base.png"));flow!.Save(Path.Combine(folder,"flow.png"));var mp=new byte[mask.Length*4];var cut=(byte[])image.Pixels.Clone();for(int i=0;i<mask.Length;i++){mp[i*4]=mp[i*4+1]=mp[i*4+2]=mask[i];mp[i*4+3]=255;cut[i*4+3]=(byte)(cut[i*4+3]*(255-mask[i])/255);}new Raster(image.W,image.H,mp).Save(Path.Combine(folder,"mask.png"));new Raster(image.W,image.H,cut).Save(Path.Combine(folder,"cutout.png"));File.WriteAllText(Path.Combine(folder,"session.json"),JsonSerializer.Serialize(settings,Json));}
 async void SaveSession(object s,RoutedEventArgs e){var d=new SaveFileDialog{Filter="Texture Flow session|*.tflow"};if(d.ShowDialog()!=true)return;await Work(async()=>{Check();if(flow==null)throw new Exception("Open a flow texture first.");var settings=Settings();await Task.Run(()=>{string dir=d.FileName+".assets";Directory.CreateDirectory(dir);WriteAssets(dir,settings);File.WriteAllText(d.FileName,JsonSerializer.Serialize(new{assets=Path.GetFileName(dir)}));});Status.Text="Session saved with its textures and editable mask.";});}
 async void LoadSession(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="Texture Flow session|*.tflow"};if(d.ShowDialog()!=true)return;await Work(async()=>{string root=Path.GetDirectoryName(d.FileName)!;using var j=JsonDocument.Parse(File.ReadAllText(d.FileName));string dir=Path.GetFullPath(Path.Combine(root,j.RootElement.GetProperty("assets").GetString()!));if(!dir.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Session assets must be beside the session file.");var loaded=await Task.Run(()=>(Raster.Load(Path.Combine(dir,"base.png")),Raster.Load(Path.Combine(dir,"flow.png")),Raster.Load(Path.Combine(dir,"mask.png")),JsonSerializer.Deserialize<FlowSettings>(File.ReadAllText(Path.Combine(dir,"session.json")),Json)!));if(loaded.Item3.W!=loaded.Item1.W||loaded.Item3.H!=loaded.Item1.H)throw new Exception("Mask dimensions do not match.");SetImage(loaded.Item1);flow=loaded.Item2;FlowLabel.Text="Saved moving texture";Steps.SelectedIndex=1;for(int i=0;i<mask.Length;i++)mask[i]=loaded.Item3.Pixels[i*4];var c=loaded.Item4;Speed.Text=c.speed.ToString(System.Globalization.CultureInfo.InvariantCulture);Angle.Value=c.angle;TileX.Text=c.tilingX.ToString(System.Globalization.CultureInfo.InvariantCulture);TileY.Text=c.tilingY.ToString(System.Globalization.CultureInfo.InvariantCulture);Rotation.Text=c.rotation.ToString(System.Globalization.CultureInfo.InvariantCulture);Emission.Text=c.emission.ToString(System.Globalization.CultureInfo.InvariantCulture);Hdr.Text=c.hdr.ToString(System.Globalization.CultureInfo.InvariantCulture);Tint.Text=c.tint;Shader.SelectedIndex=c.shader=="Poiyomi"?1:c.shader=="lilToon"?2:0;});}
